// In-memory comment store - persists for the lifetime of the server process

export interface Comment {
  id: string
  parentId: string | null
  body: string
  createdAt: number
}

const comments: Comment[] = []
let nextId = 1

export function getComments(): Comment[] {
  return comments
}

export function createComment(parentId: string | null, body: string): Comment {
  const comment: Comment = {
    id: String(nextId++),
    parentId,
    body,
    createdAt: Date.now(),
  }
  comments.push(comment)
  return comment
}

import type { IncomingMessage, ServerResponse } from 'node:http'
import { getComments, createComment } from './comments-store.js'

export async function handleApiComments(
  req: IncomingMessage,
  res: ServerResponse,
): Promise<boolean> {
  const url = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`)

  if (url.pathname !== '/api/comments') {
    return false
  }

  if (req.method === 'GET') {
    const data = getComments()
    res.writeHead(200, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify(data))
    return true
  }

  if (req.method === 'POST') {
    // Check for fail query parameter
    const fail = url.searchParams.get('fail')
    if (fail === '1') {
      res.writeHead(500, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ error: 'Server error' }))
      return true
    }

    // Artificial delay of at least 300ms
    await new Promise((resolve) => setTimeout(resolve, 300))

    // Parse request body
    const body = await new Promise<string>((resolve) => {
      let data = ''
      req.on('data', (chunk: string) => {
        data += chunk
      })
      req.on('end', () => {
        resolve(data)
      })
    })

    let parsed: { parentId?: string | null; body?: string }
    try {
      parsed = JSON.parse(body)
    } catch {
      res.writeHead(400, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ error: 'Invalid JSON' }))
      return true
    }

    const newComment = createComment(parsed.parentId ?? null, parsed.body || '')
    res.writeHead(200, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify(newComment))
    return true
  }

  res.writeHead(405, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify({ error: 'Method not allowed' }))
  return true
}

import type { Plugin } from 'vite'
import type { IncomingMessage, ServerResponse } from 'node:http'

export function apiCommentsPlugin(): Plugin {
  return {
    name: 'api-comments-plugin',
    configureServer(server) {
      server.middlewares.use(async (req: IncomingMessage, res: ServerResponse, next: () => void) => {
        const url = req.url || '/'

        // Only handle /api/comments
        if (!url.startsWith('/api/comments')) {
          return next()
        }

        // Dynamic import to avoid bundling the store into the client
        const { handleApiComments } = await import('./api-handler.js')
        const handled = await handleApiComments(req, res)
        if (!handled) {
          next()
        }
      })
    },
  }
}

