// Custom production server that handles /api/comments and delegates to TanStack Start
import { createServer } from 'node:http'
import { handleApiComments } from './dist/server/comments-api.js'

// Import the TanStack Start server handler
import server from './dist/server/server.js'

const PORT = parseInt(process.env.PORT || '47821', 10)

const httpServer = createServer(async (req, res) => {
  // Handle /api/comments routes
  const handled = await handleApiComments(req, res)
  if (handled) return

  // Delegate all other requests to TanStack Start
  try {
    const url = new URL(req.url || '/', `http://${req.headers.host || `localhost:${PORT}`}`)
    const headers = new Headers()
    for (const [key, value] of Object.entries(req.headers)) {
      if (value) {
        headers.set(key, Array.isArray(value) ? value.join(', ') : value)
      }
    }

    // Collect request body
    const chunks: Uint8Array[] = []
    for await (const chunk of req) {
      chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk)
    }
    const body = Buffer.concat(chunks)

    const request = new Request(url.toString(), {
      method: req.method,
      headers,
      body: req.method !== 'GET' && req.method !== 'HEAD' ? body : undefined,
    })

    const response = await server.fetch(request)

    res.writeHead(response.status, Object.fromEntries(response.headers.entries()))
    const responseBody = await response.arrayBuffer()
    res.end(Buffer.from(responseBody))
  } catch (err) {
    console.error('Error handling request:', err)
    res.writeHead(500, { 'Content-Type': 'text/plain' })
    res.end('Internal Server Error')
  }
})

httpServer.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`)
})
